SET search_path=elite_diary,public;
ALTER TABLE users DROP CONSTRAINT IF EXISTS users_role_check;
ALTER TABLE users ADD CONSTRAINT users_role_check CHECK(role IN('super_admin','school_admin','coordinator','head_teacher','teacher','parent'));
CREATE TABLE IF NOT EXISTS school_nodes(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('branch','campus')),name TEXT NOT NULL,parent_id TEXT REFERENCES school_nodes(id),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS class_campuses(class_id TEXT PRIMARY KEY REFERENCES academics(id),campus_id TEXT NOT NULL REFERENCES school_nodes(id));
CREATE TABLE IF NOT EXISTS section_subjects(section_id TEXT NOT NULL REFERENCES academics(id),subject_id TEXT NOT NULL REFERENCES academics(id),PRIMARY KEY(section_id,subject_id));
CREATE TABLE IF NOT EXISTS parent_sections(parent_id TEXT NOT NULL REFERENCES users(id),section_id TEXT NOT NULL REFERENCES academics(id),child_name TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),PRIMARY KEY(parent_id,section_id));
CREATE TABLE IF NOT EXISTS role_capabilities(role TEXT PRIMARY KEY,grants TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_capabilities(user_id TEXT PRIMARY KEY REFERENCES users(id),allows TEXT NOT NULL,denies TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS school_diaries(id TEXT PRIMARY KEY,teacher_id TEXT NOT NULL REFERENCES users(id),head_id TEXT NOT NULL REFERENCES users(id),section_id TEXT NOT NULL REFERENCES academics(id),diary_date TEXT NOT NULL,language TEXT NOT NULL CHECK(language IN('en','ur')),status TEXT NOT NULL CHECK(status IN('draft','submitted','under_review','returned','resubmitted','approved')),version INTEGER NOT NULL DEFAULT 1,content TEXT NOT NULL,snapshot TEXT NOT NULL,quote_payload TEXT NOT NULL,remarks TEXT NOT NULL DEFAULT '',submitted_at TEXT,reviewed_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(teacher_id,section_id,diary_date));
CREATE TABLE IF NOT EXISTS school_diary_versions(id TEXT PRIMARY KEY,diary_id TEXT NOT NULL REFERENCES school_diaries(id),version INTEGER NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,remarks TEXT NOT NULL,snapshot TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(diary_id,version));
CREATE TABLE IF NOT EXISTS push_subscriptions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),endpoint TEXT NOT NULL UNIQUE,p256dh TEXT NOT NULL,auth TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS push_preferences(user_id TEXT PRIMARY KEY REFERENCES users(id),enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)));
CREATE TABLE IF NOT EXISTS push_deliveries(notification_id TEXT NOT NULL REFERENCES notifications(id),subscription_id TEXT NOT NULL REFERENCES push_subscriptions(id),status TEXT NOT NULL CHECK(status IN('pending','sending','sent','failed','expired')),attempts INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL,error_code TEXT,PRIMARY KEY(notification_id,subscription_id));
CREATE INDEX IF NOT EXISTS school_diaries_section_date ON school_diaries(section_id,diary_date,status);
CREATE INDEX IF NOT EXISTS school_diaries_reviewer ON school_diaries(head_id,status);
CREATE INDEX IF NOT EXISTS school_diaries_teacher ON school_diaries(teacher_id,diary_date);
DROP TRIGGER IF EXISTS immutable_history ON school_diary_versions;
CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON school_diary_versions FOR EACH ROW EXECUTE FUNCTION elite_diary.prevent_history_mutation();
ALTER TABLE school_nodes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON school_nodes FROM PUBLIC,anon,authenticated;
ALTER TABLE class_campuses ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON class_campuses FROM PUBLIC,anon,authenticated;
ALTER TABLE section_subjects ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON section_subjects FROM PUBLIC,anon,authenticated;
ALTER TABLE parent_sections ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON parent_sections FROM PUBLIC,anon,authenticated;
ALTER TABLE role_capabilities ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON role_capabilities FROM PUBLIC,anon,authenticated;
ALTER TABLE user_capabilities ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON user_capabilities FROM PUBLIC,anon,authenticated;
ALTER TABLE school_diaries ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON school_diaries FROM PUBLIC,anon,authenticated;
ALTER TABLE school_diary_versions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON school_diary_versions FROM PUBLIC,anon,authenticated;
ALTER TABLE push_subscriptions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON push_subscriptions FROM PUBLIC,anon,authenticated;
ALTER TABLE push_preferences ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON push_preferences FROM PUBLIC,anon,authenticated;
ALTER TABLE push_deliveries ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON push_deliveries FROM PUBLIC,anon,authenticated;
INSERT INTO migrations VALUES(4,to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) ON CONFLICT DO NOTHING;
RESET search_path;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='elite_diary_app') THEN
GRANT SELECT,INSERT,UPDATE,DELETE ON elite_diary.school_nodes TO elite_diary_app;
IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='elite_diary' AND tablename='school_nodes' AND policyname='server_application') THEN CREATE POLICY server_application ON elite_diary.school_nodes FOR ALL TO elite_diary_app USING(true) WITH CHECK(true); END IF;
