GRANT SELECT,INSERT,UPDATE,DELETE ON elite_diary.user_capabilities TO elite_diary_app;
IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='elite_diary' AND tablename='user_capabilities' AND policyname='server_application') THEN CREATE POLICY server_application ON elite_diary.user_capabilities FOR ALL TO elite_diary_app USING(true) WITH CHECK(true); END IF;
GRANT SELECT,INSERT,UPDATE,DELETE ON elite_diary.school_diaries TO elite_diary_app;
IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='elite_diary' AND tablename='school_diaries' AND policyname='server_application') THEN CREATE POLICY server_application ON elite_diary.school_diaries FOR ALL TO elite_diary_app USING(true) WITH CHECK(true); END IF;
GRANT SELECT,INSERT,UPDATE,DELETE ON elite_diary.school_diary_versions TO elite_diary_app;
IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='elite_diary' AND tablename='school_diary_versions' AND policyname='server_application') THEN CREATE POLICY server_application ON elite_diary.school_diary_versions FOR ALL TO elite_diary_app USING(true) WITH CHECK(true); END IF;
GRANT SELECT,INSERT,UPDATE,DELETE ON elite_diary.push_subscriptions TO elite_diary_app;
IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='elite_diary' AND tablename='push_subscriptions' AND policyname='server_application') THEN CREATE POLICY server_application ON elite_diary.push_subscriptions FOR ALL TO elite_diary_app USING(true) WITH CHECK(true); END IF;
GRANT SELECT,INSERT,UPDATE,DELETE ON elite_diary.push_preferences TO elite_diary_app;
IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='elite_diary' AND tablename='push_preferences' AND policyname='server_application') THEN CREATE POLICY server_application ON elite_diary.push_preferences FOR ALL TO elite_diary_app USING(true) WITH CHECK(true); END IF;
GRANT SELECT,INSERT,UPDATE,DELETE ON elite_diary.push_deliveries TO elite_diary_app;
IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='elite_diary' AND tablename='push_deliveries' AND policyname='server_application') THEN CREATE POLICY server_application ON elite_diary.push_deliveries FOR ALL TO elite_diary_app USING(true) WITH CHECK(true); END IF;
END IF; END $$;
